// Narration proxy (Cloudflare Worker). Keeps the Anthropic API key off phones.
//
// Deploy (from proxy/):
//   npx wrangler login
//   npx wrangler deploy
//   npx wrangler secret put ANTHROPIC_API_KEY
// Then in the app: Settings → Endpoint = the worker URL, leave API key empty.
//
// Abuse controls — this endpoint is public, so assume hostile callers:
//   • Origin allowlist (ALLOWED_ORIGINS in wrangler.toml). Stops other websites
//     from using it from a browser; does NOT stop scripts that forge Origin.
//   • Per-IP rate limit (NARRATE_LIMITER binding) — the real cost bound.
//   • The client's prompt is ignored. The request is rebuilt from whitelisted,
//     clamped event fields; model and max_tokens are fixed here. At worst a
//     caller gets short Lao sentences about sound events.
//   • Set a monthly spend limit on the Anthropic key's workspace as a backstop.

import { SYSTEM_PROMPT } from '../js/narrate.js';

const MODEL = 'claude-opus-5';
const MAX_BODY_BYTES = 16_000;
const MAX_EVENTS = 15;
const UPSTREAM_TIMEOUT_MS = 25_000;
const TIERS = new Set(['danger', 'caution', 'info']);
const SOURCES = new Set(['yamnet', 'personal']);

function allowedOrigins(env) {
  return (env.ALLOWED_ORIGINS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
}

function corsHeaders(origin) {
  return {
    'access-control-allow-origin': origin,
    'access-control-allow-methods': 'POST, OPTIONS',
    'access-control-allow-headers': 'content-type',
    'access-control-max-age': '86400',
    vary: 'Origin',
  };
}

function json(status, data, headers = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'content-type': 'application/json', 'cache-control': 'no-store', ...headers },
  });
}

const text = (v, max) => String(v ?? '').replace(/[�-]/g, ' ').slice(0, max);
const clamp = (v, lo, hi) => {
  const n = Number(v);
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : lo;
};

// Returns sanitized events, or null if the payload isn't a narration request.
export function sanitizeEvents(body) {
  let events;
  try {
    events = JSON.parse(body?.messages?.[0]?.content)?.events;
  } catch {
    return null;
  }
  if (!Array.isArray(events) || events.length === 0 || events.length > MAX_EVENTS) return null;
  const clean = [];
  for (const e of events) {
    if (!e || typeof e !== 'object' || !TIERS.has(e.tier) || !SOURCES.has(e.source)) return null;
    clean.push({
      class: text(e.class, 60),
      label_lo: text(e.label_lo, 60),
      source: e.source,
      tier: e.tier,
      confidence: Math.round(clamp(e.confidence, 0, 1) * 100) / 100,
      seconds_ago: Math.round(clamp(e.seconds_ago, 0, 3600)),
      timestamp: text(e.timestamp, 30),
    });
  }
  return clean;
}

export default {
  async fetch(request, env) {
    const origin = request.headers.get('origin') ?? '';
    const originOk = allowedOrigins(env).includes(origin);
    const cors = originOk ? corsHeaders(origin) : { vary: 'Origin' };

    if (new URL(request.url).pathname !== '/') return json(404, { error: 'not_found' }, cors);
    if (request.method === 'OPTIONS') {
      return originOk ? new Response(null, { status: 204, headers: cors }) : json(403, { error: 'origin_not_allowed' });
    }
    if (request.method !== 'POST') return json(405, { error: 'method_not_allowed' }, { ...cors, allow: 'POST, OPTIONS' });
    if (!originOk) return json(403, { error: 'origin_not_allowed' });

    const ip = request.headers.get('cf-connecting-ip') ?? 'unknown';
    if (env.NARRATE_LIMITER) {
      const { success } = await env.NARRATE_LIMITER.limit({ key: ip });
      if (!success) return json(429, { error: 'rate_limited' }, { ...cors, 'retry-after': '60' });
    }

    if (!env.ANTHROPIC_API_KEY) {
      console.error('ANTHROPIC_API_KEY secret is not set');
      return json(503, { error: 'not_configured' }, cors);
    }

    const length = Number(request.headers.get('content-length') ?? 0);
    if (length > MAX_BODY_BYTES) return json(413, { error: 'too_large' }, cors);
    const raw = await request.text();
    if (raw.length > MAX_BODY_BYTES) return json(413, { error: 'too_large' }, cors);

    let body;
    try {
      body = JSON.parse(raw);
    } catch {
      return json(400, { error: 'bad_json' }, cors);
    }
    const events = sanitizeEvents(body);
    if (!events) return json(400, { error: 'bad_request' }, cors);

    let upstream;
    try {
      upstream = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        signal: AbortSignal.timeout(UPSTREAM_TIMEOUT_MS),
        headers: {
          'content-type': 'application/json',
          'x-api-key': env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'anthropic-beta': 'server-side-fallback-2026-07-01',
        },
        body: JSON.stringify({
          model: MODEL,
          max_tokens: 2048,
          system: SYSTEM_PROMPT,
          output_config: { effort: 'low' },
          fallbacks: 'default',
          messages: [{ role: 'user', content: JSON.stringify({ events }) }],
        }),
      });
    } catch (err) {
      console.error('upstream fetch failed', err.name, err.message);
      return json(504, { error: 'upstream_unavailable' }, cors);
    }

    if (!upstream.ok) {
      // Log the detail server-side; never echo Anthropic error bodies to clients.
      console.error('upstream error', upstream.status, await upstream.text().catch(() => ''));
      const status = upstream.status === 429 || upstream.status === 529 ? 503 : 502;
      return json(status, { error: 'upstream_error' }, cors);
    }

    const msg = await upstream.json();
    // Return only what the app reads.
    return json(200, { model: msg.model, stop_reason: msg.stop_reason, content: (msg.content ?? []).filter((b) => b.type === 'text') }, cors);
  },
};
